    internal static bool HasFit(string handModel, int appearance) =>
        TryGetFit(handModel, appearance, out _);

    internal static bool TryGetScale(string handModel, int appearance, out float scale)
    {
        var found = TryGetFit(handModel, appearance, out var fit);
        scale = found ? fit.Scale : 1f;
        return found;
    }

    internal static bool TryGetTranslation(string handModel, int appearance, float sharedScale,
        out FitVector translation)
    {
        var found = TryGetFit(handModel, appearance, out var fit);
        // A larger opposite hand changes the shared scale, but never the local grip target.
        translation = found ? fit.TargetCenter - sharedScale * fit.AuthoredCenter : FitVector.Zero;
        return found;
    }

    private static bool TryGetFit(string handModel, int appearance,
        out (float Scale, FitVector AuthoredCenter, FitVector TargetCenter) fit)
    {
        fit = default;
        return !string.IsNullOrWhiteSpace(handModel) && Fits.TryGetValue(handModel, out var appearances) &&
               appearances.TryGetValue(appearance, out fit);
    }
}
